CREATE TABLE projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id), code VARCHAR(40) NOT NULL, name VARCHAR(180) NOT NULL, description TEXT, start_date DATE, end_date DATE, status VARCHAR(20) NOT NULL CHECK(status IN ('DRAFT','ACTIVE','COMPLETED','SUSPENDED','ARCHIVED')), created_by UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,code), CHECK(end_date IS NULL OR start_date IS NULL OR end_date>=start_date));
CREATE INDEX projects_org_status_idx ON projects(organization_id,status);
